BEGIN;
SELECT plan(25);
INSERT INTO public.profiles(id,anonymous) VALUES ('16100000-0000-4000-8000-000000000003',false);
SELECT ok((SELECT count(*)=0 FROM public.plants WHERE owner_id='16100000-0000-4000-8000-000000000003'), 'Free starts at zero');
SELECT lives_ok($q$SELECT public.execute_plant_create_command('16100000-0000-4000-8000-000000000003', '16100000-0000-4000-8000-000000000001', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Free creates instance 1');
SELECT lives_ok($q$SELECT public.execute_plant_create_command('16100000-0000-4000-8000-000000000003', '16100000-0000-4000-8000-000000000002', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Free creates instance 2');
SELECT lives_ok($q$SELECT public.execute_plant_create_command('16100000-0000-4000-8000-000000000003', '16100000-0000-4000-8000-000000000003', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Free creates instance 3');
SELECT throws_ok($q$SELECT public.execute_plant_create_command('16100000-0000-4000-8000-000000000003', '16100000-0000-4000-8000-000000000004', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Free fourth create rejected');
SELECT ok((SELECT count(*)=3 FROM public.plants WHERE owner_id='16100000-0000-4000-8000-000000000003' AND deleted_at IS NULL), 'Free cap counts instances');
SELECT lives_ok($q$SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000001', '16100000-0000-4000-8000-000000000011', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Free with two creates third');
SELECT lives_ok($q$SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000001', '16100000-0000-4000-8000-000000000011', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Exact retry at cap succeeds');
SELECT ok((SELECT count(*)=1 FROM public.operation_receipts WHERE owner_id='15800000-0000-4000-8000-000000000001' AND operation_id='16100000-0000-4000-8000-000000000011'), 'Retry keeps one receipt');
SELECT throws_ok($q$SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000001', '16100000-0000-4000-8000-000000000012', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Free at three rejects another operation');
SELECT throws_ok($q$INSERT INTO public.plants(owner_id,creation_source,display_name) VALUES ('15800000-0000-4000-8000-000000000001','guest_claim','No bypass')$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Guest writer cannot bypass table cap');
SELECT throws_ok($q$INSERT INTO public.plants(owner_id,creation_source,display_name) VALUES ('15800000-0000-4000-8000-000000000001','local_fallback','No bypass')$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Legacy fallback cannot bypass table cap');
SELECT lives_ok($q$UPDATE public.plants SET deleted_at=clock_timestamp() WHERE id='15800000-0000-4000-8000-000000000201'; SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000001', '16100000-0000-4000-8000-000000000013', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Soft deletion releases capacity');
SELECT throws_ok($q$UPDATE public.plants SET deleted_at=NULL WHERE id='15800000-0000-4000-8000-000000000201'$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Undelete cannot bypass cap');
SELECT lives_ok($q$INSERT INTO public.entitlements(owner_id,product_id,state,offer_kind,valid_until) VALUES ('15800000-0000-4000-8000-000000000002','app.narat.plants.pro.monthly','active','paid',now()+interval '1 day'); SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000002', '16100000-0000-4000-8000-000000000020', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb); SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000002', '16100000-0000-4000-8000-000000000021', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb); SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000002', '16100000-0000-4000-8000-000000000022', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb); SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000002', '16100000-0000-4000-8000-000000000023', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'Paid creates beyond three');
SELECT ok((SELECT count(*)=5 FROM public.plants WHERE owner_id='15800000-0000-4000-8000-000000000002' AND deleted_at IS NULL), 'Paid collection has five instances');
SELECT throws_ok($q$UPDATE public.plants SET owner_id='15800000-0000-4000-8000-000000000001' WHERE id='15800000-0000-4000-8000-000000000202'$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Owner transfer cannot bypass cap');
SELECT lives_ok($q$UPDATE public.entitlements SET state='expired',valid_until=now()-interval '1 second' WHERE owner_id='15800000-0000-4000-8000-000000000002'$q$, 'Expiry preserves collection');
SELECT throws_ok($q$SELECT public.execute_plant_create_command('15800000-0000-4000-8000-000000000002', '16100000-0000-4000-8000-000000000029', '{"plant_id":"fixture_rooms_plant","display_name":"New"}'::jsonb)$q$, 'P0001', 'COLLECTION_LIMIT_REACHED', 'Expired owner above cap cannot add');
SELECT ok((SELECT count(*)=5 FROM public.plants WHERE owner_id='15800000-0000-4000-8000-000000000002' AND deleted_at IS NULL), 'Expiry keeps all saved instances');
SELECT ok((SELECT consumed_count=7 AND reserved_count=1 FROM public.monthly_quotas WHERE id='15800000-0000-4000-8000-000000000601'), 'Quota spending is retained');
SELECT ok((SELECT has_function_privilege('service_role','public.execute_plant_create_command(uuid,uuid,jsonb,timestamptz)','EXECUTE') AND NOT has_function_privilege('authenticated','public.execute_plant_create_command(uuid,uuid,jsonb,timestamptz)','EXECUTE')), 'RPC service-only grants retained');
SELECT lives_ok($q$GRANT SELECT ON public.plants TO authenticated; SET LOCAL ROLE authenticated; SET LOCAL request.jwt.claim.sub='15800000-0000-4000-8000-000000000001'$q$, 'Use real authenticated RLS context');
SELECT ok((SELECT count(*)=0 FROM public.plants WHERE owner_id<>'15800000-0000-4000-8000-000000000001'), 'RLS hides other owner instances');
SELECT lives_ok($q$RESET ROLE$q$, 'Leave RLS context');
SELECT * FROM finish();
ROLLBACK;
